// @ts-check

/**
 * Groups the top-level items of the autogenerated docs sidebar under section
 * labels (GETTING STARTED, USER MANUAL, ...).
 *
 * A section is a non-collapsible category marked with `customProps.section`,
 * which `src/theme/DocSidebarItem` renders as a small label with its items
 * beneath. Each top-level folder of `docs/` is assigned to a section by name.
 * A folder listed in `flatten` contributes its pages directly instead of as a
 * nested category; the section then takes over that category's link, so a
 * generated index page keeps its URL.
 *
 * Folders not assigned to any section keep their place after the sections.
 */

/** @type {{key: string, label: string, dirs: string[], flatten?: string[]}[]} */
const SECTIONS = [
  {
    key: "section-getting-started",
    label: "Getting started",
    dirs: ["getting_started"],
    flatten: ["getting_started"],
  },
  {
    key: "section-user-manual",
    label: "User manual",
    dirs: ["workspace", "goat_ai", "data", "map", "toolbox", "workflows", "layouts", "builder", "sharing", "routing"],
  },
  {
    key: "section-self-hosting",
    label: "Self-hosting",
    dirs: ["self_hosting"],
    flatten: ["self_hosting"],
  },
  {
    key: "section-help",
    label: "Help",
    dirs: ["support", "further_reading", "nerdy_content"],
  },
];

/**
 * The top-level folder an autogenerated sidebar item comes from, taken from
 * the id of the first doc it contains.
 * @param {any} item
 * @returns {string | undefined}
 */
function topLevelDir(item) {
  if (item.type === "doc" || item.type === "ref") {
    return item.id.split("/")[0];
  }
  if (item.type === "category") {
    if (item.link && item.link.type === "doc") {
      return item.link.id.split("/")[0];
    }
    for (const child of item.items) {
      const dir = topLevelDir(child);
      if (dir) {
        return dir;
      }
    }
  }
  return undefined;
}

/**
 * @param {any[]} items the autogenerated items of the docs root
 * @returns {any[]}
 */
function groupIntoSections(items) {
  const byDir = new Map();
  const unassigned = [];
  const assignedDirs = new Set(SECTIONS.flatMap((section) => section.dirs));
  for (const item of items) {
    const dir = topLevelDir(item);
    if (dir && assignedDirs.has(dir)) {
      byDir.set(item, dir);
    } else {
      unassigned.push(item);
    }
  }

  const sections = [];
  for (const section of SECTIONS) {
    const members = items.filter((item) => section.dirs.includes(byDir.get(item)));
    if (members.length === 0) {
      continue;
    }
    let link;
    const sectionItems = [];
    for (const member of members) {
      const flatten = member.type === "category" && (section.flatten || []).includes(byDir.get(member));
      if (flatten) {
        link = link || member.link;
        sectionItems.push(...member.items);
      } else {
        sectionItems.push(member);
      }
    }
    sections.push({
      type: "category",
      key: section.key,
      label: section.label,
      collapsible: false,
      collapsed: false,
      className: "sidebar-section",
      customProps: { section: true },
      ...(link ? { link } : {}),
      items: sectionItems,
    });
  }
  return [...sections, ...unassigned];
}

/**
 * The glossary lives on the Plan4Better website. Its sidebar entry sits in the
 * Literature folder, ahead of the publications, and opens the website glossary
 * in the reader's language.
 * @param {any[]} items the autogenerated items of the docs root
 */
function addGlossaryLink(items) {
  const german = process.env.DOCUSAURUS_CURRENT_LOCALE === "de";
  const glossary = {
    type: "link",
    label: german ? "Glossar" : "Glossary",
    href: german ? "https://www.plan4better.de/de/glossar" : "https://www.plan4better.de/en/glossary",
  };
  for (const item of items) {
    if (item.type === "category" && topLevelDir(item) === "further_reading") {
      item.items = [glossary, ...item.items];
    }
  }
  return items;
}

/** @type {import('@docusaurus/plugin-content-docs').PluginOptions['sidebarItemsGenerator']} */
async function sidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  const items = await defaultSidebarItemsGenerator(args);
  if (args.item.dirName !== ".") {
    return items;
  }
  return groupIntoSections(addGlossaryLink(items));
}

module.exports = { sidebarItemsGenerator };
